  "track.runtime.m.records.met.conflicts": "Conflicts",
  "track.runtime.m.records.met.records": "Records",
  "track.runtime.m.records.st.records": "Records (snapshot id = value)",
  "track.runtime.m.records.st.global": "Global reads",
